    def test_direction_1(self: Self) -> None:
        """Tests parsing a list of directions (tram)"""
        directions = [{"route_direction_description": "Trams commence at the Vermont South Shopping Centre near Hanover Rd (Vermont South) and run via Burwood Hiwy, Toorak Rd, Camberwell Rd, Riversdale Rd, Power St, Burwood Rd, Bridge Rd, Wellington Pde, Flinders St (City) to terminate near Marvel Stadium Docklands at the coner of Latrobe Street (City).",
                       "direction_id": 14,
                       "direction_name": "Central Pier Docklands",
                       "route_id": 958,
                       "route_type": 1
                       },
                      {"route_direction_description": "Trams commence in Harbour Esp, near Marvel Stadium Docklands at the corner of Latrobe St (City) and run via  Flinders St (City), Wellington Pde, Bridge Rd, Burwood Rd, Power St, Riversdale Rd, Camberwell Rd, Toorak Rd and Burwood Hwy to terminate at the Vermont South Shopping Centre near Hanover Road (Vermont South).",
                       "direction_id": 29,
                       "direction_name": "Vermont South",
                       "route_id": 958,
                       "route_type": 1
                       }
                      ]
        self.assertEqual(
            [Direction.load(**direction) for direction in directions],
            [Direction(route_direction_description="Trams commence at the Vermont South Shopping Centre near Hanover Rd (Vermont South) and run via Burwood Hiwy, Toorak Rd, Camberwell Rd, Riversdale Rd, Power St, Burwood Rd, Bridge Rd, Wellington Pde, Flinders St (City) to terminate near Marvel Stadium Docklands at the coner of Latrobe Street (City).",
                       direction_id=14,
                       direction_name="Central Pier Docklands",
                       route_id=958,
                       route_type=1
                       ),
             Direction(route_direction_description="Trams commence in Harbour Esp, near Marvel Stadium Docklands at the corner of Latrobe St (City) and run via  Flinders St (City), Wellington Pde, Bridge Rd, Burwood Rd, Power St, Riversdale Rd, Camberwell Rd, Toorak Rd and Burwood Hwy to terminate at the Vermont South Shopping Centre near Hanover Road (Vermont South).",
                       direction_id=29,
                       direction_name="Vermont South",
                       route_id=958,
                       route_type=1
                       )
             ]
        )
        return

